use clap::{App, Arg};
use regex::Regex;
use std::io::{self, BufRead};
use std::process::{Command, Stdio};
use std::thread;
use std::time::{Duration, Instant};
use std::env;
use chrono::NaiveDateTime;

fn main() {
    let matches = App::new("loop")
        .version("0.6.1")
        .author("Rich Jones <miserlou@gmail.com>")
        .about("UNIX's missing `loop` command")
        .arg(
            Arg::with_name("num")
                .short("n")
                .long("num")
                .value_name("NUM")
                .help("Number of iterations to execute")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("every")
                .short("e")
                .long("every")
                .value_name("EVERY")
                .help("How often to iterate. ex., 5s, 1h1m1s1ms1us")
                .default_value("1us")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("count_by")
                .short("b")
                .long("count-by")
                .value_name("COUNT_BY")
                .help("Amount to increment the counter by")
                .default_value("1")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("offset")
                .short("o")
                .long("offset")
                .value_name("OFFSET")
                .help("Amount to offset the initial counter by")
                .default_value("0")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("for")
                .long("for")
                .value_name("FOR")
                .help("A comma-separated list of values, placed into $ITEM")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("for_duration")
                .short("d")
                .long("for-duration")
                .value_name("FOR_DURATION")
                .help("Keep going until the duration has elapsed (example 1m30s)")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("until_contains")
                .short("c")
                .long("until-contains")
                .value_name("UNTIL_CONTAINS")
                .help("Keep going until the output contains this string")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("until_match")
                .short("m")
                .long("until-match")
                .value_name("UNTIL_MATCH")
                .help("Keep going until the output matches this regular expression")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("until_success")
                .short("s")
                .long("until-success")
                .help("Keep going until the command exit status is zero")
        )
        .arg(
            Arg::with_name("until_fail")
                .short("f")
                .long("until-fail")
                .help("Keep going until the command exit status is non-zero")
        )
        .arg(
            Arg::with_name("until_error")
                .short("r")
                .long("until-error")
                .value_name("UNTIL_ERROR")
                .help("Keep going until the command exit status is the value given")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("until_changes")
                .short("C")
                .long("until-changes")
                .help("Keep going until the output changes")
        )
        .arg(
            Arg::with_name("until_same")
                .short("S")
                .long("until-same")
                .help("Keep going until the output changes")
        )
        .arg(
            Arg::with_name("until_time")
                .short("t")
                .long("until-time")
                .value_name("UNTIL_TIME")
                .help("Keep going until a future time, ex. \"2018-04-20 04:20:00\" (Times in UTC.)")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("stdin")
                .short("i")
                .long("stdin")
                .help("Read from standard input")
        )
        .arg(
            Arg::with_name("only_last")
                .short("l")
                .long("only-last")
                .help("Only print the output of the last execution of the command")
        )
        .arg(
            Arg::with_name("summary")
                .long("summary")
                .help("Provide a summary")
        )
        .arg(
            Arg::with_name("error_duration")
                .short("D")
                .long("error-duration")
                .help("Exit with timeout error code on duration")
        )
        .arg(
            Arg::with_name("input")
                .value_name("input")
                .help("The command to be looped")
                .multiple(true)
        )
        .get_matches();

    // Parse arguments
    let num_iterations: Option<usize> = matches.value_of("num").and_then(|n| n.parse().ok());
    let every_str = matches.value_of("every").unwrap_or("1us");
    let count_by: i64 = matches.value_of("count_by").unwrap_or("1").parse().unwrap_or(1);
    let offset: i64 = matches.value_of("offset").unwrap_or("0").parse().unwrap_or(0);
    let until_contains = matches.value_of("until_contains");
    let until_match_str = matches.value_of("until_match");
    let until_success = matches.is_present("until_success");
    let until_fail = matches.is_present("until_fail");
    let until_error: Option<i32> = matches.value_of("until_error").and_then(|e| e.parse().ok());
    let until_changes = matches.is_present("until_changes");
    let until_same = matches.is_present("until_same");
    let until_time_str = matches.value_of("until_time");
    let read_stdin = matches.is_present("stdin");
    let only_last = matches.is_present("only_last");
    let show_summary = matches.is_present("summary");
    let error_duration = matches.is_present("error_duration");
    let for_list = matches.value_of("for");
    let for_duration_str = matches.value_of("for_duration");

    let delay = parse_duration(every_str);
    let for_duration = for_duration_str.map(parse_duration);

    let input: Vec<String> = matches
        .values_of("input")
        .map(|v| v.map(String::from).collect())
        .unwrap_or_default();

    // Compile regex if provided
    let until_match_re = until_match_str.map(|r| Regex::new(r).expect("Invalid regex"));

    let mut successes = 0;
    let mut failures = 0;
    let mut iterations = 0;
    let mut last_output = String::new();

    // Parse until_time
    let until_time_instant = until_time_str.map(|t| {
        NaiveDateTime::parse_from_str(t, "%Y-%m-%d %H:%M:%S")
            .ok()
            .and_then(|dt| {
                let now = chrono::Utc::now().naive_utc();
                let duration_secs = (dt.timestamp() - now.timestamp()) as u64;
                Some(Instant::now() + Duration::from_secs(duration_secs))
            })
    });

    let duration_start = Instant::now();
    let duration_end = for_duration.map(|d| duration_start + d);

    let items: Vec<String> = if let Some(list) = for_list {
        list.split(',').map(String::from).collect()
    } else {
        vec![]
    };

    let stdin_lines: Vec<String> = if read_stdin {
        io::stdin()
            .lock()
            .lines()
            .filter_map(Result::ok)
            .collect()
    } else {
        vec![]
    };

    let mut counter = offset;
    let mut should_loop = true;
    let start_time = Instant::now();

    loop {
        if !should_loop {
            break;
        }

        // Check iteration limits
        if let Some(max) = num_iterations {
            if iterations >= max {
                break;
            }
        }

        // Check for-duration
        if let Some(end) = duration_end {
            if Instant::now() >= end {
                break;
            }
        }

        // Check until-time
        if let Some(Some(end_time)) = until_time_instant {
            if Instant::now() >= end_time {
                break;
            }
        }

        // Determine what to iterate over
        let items_to_process: Vec<String> = if !items.is_empty() {
            items.clone()
        } else if !stdin_lines.is_empty() {
            stdin_lines.clone()
        } else {
            vec![String::new()]
        };

        for item in items_to_process {
            // Build environment
            let mut cmd_env = env::vars().collect::<Vec<_>>();
            cmd_env.push(("COUNT".to_string(), counter.to_string()));
            cmd_env.push(("ACTUALCOUNT".to_string(), iterations.to_string()));
            if !item.is_empty() && (!items.is_empty() || read_stdin) {
                cmd_env.push(("ITEM".to_string(), item.clone()));
            }

            // Execute command
            let mut cmd = Command::new("sh");
            cmd.arg("-c");

            let command_str = if input.is_empty() {
                item
            } else {
                input.join(" ")
            };

            cmd.arg(&command_str);

            for (key, value) in &cmd_env {
                cmd.env(key, value);
            }

            let output = cmd.output().unwrap_or_else(|_| {
                std::process::Command::new("sh")
                    .arg("-c")
                    .arg(&command_str)
                    .output()
                    .expect("Failed to execute command")
            });

            let stdout = String::from_utf8_lossy(&output.stdout).to_string();
            let exit_code = output.status.code().unwrap_or(1);

            if exit_code == 0 {
                successes += 1;
            } else {
                failures += 1;
            }

            last_output = stdout.clone();

            // Print output unless only_last is set
            if !only_last {
                print!("{}", stdout);
            }

            // Check stopping conditions
            if until_success && exit_code == 0 {
                should_loop = false;
                break;
            }

            if until_fail && exit_code != 0 {
                should_loop = false;
                break;
            }

            if let Some(target_error) = until_error {
                if exit_code == target_error {
                    should_loop = false;
                    break;
                }
            }

            if let Some(substr) = until_contains {
                if stdout.contains(substr) {
                    should_loop = false;
                    break;
                }
            }

            if let Some(ref re) = until_match_re {
                if re.is_match(&stdout) {
                    should_loop = false;
                    break;
                }
            }

            if until_changes && !last_output.is_empty() {
                let current_line = stdout.trim();
                let last_line = last_output.trim();
                if current_line != last_line {
                    should_loop = false;
                    break;
                }
            }

            if until_same && iterations > 0 {
                let current_line = stdout.trim();
                let last_line = last_output.trim();
                if current_line == last_line {
                    should_loop = false;
                    break;
                }
            }

            iterations += 1;
            counter += count_by;

            if !should_loop {
                break;
            }
        }

        // Print last output if only_last is set
        if only_last && iterations > 0 && should_loop {
            // Will be printed at the end
        }

        // Sleep before next iteration
        thread::sleep(delay);

        // Check if we're done
        if let Some(max) = num_iterations {
            if iterations >= max {
                break;
            }
        }

        if let Some(end) = duration_end {
            if Instant::now() >= end {
                break;
            }
        }
    }

    // Print last output if only_last is set
    if only_last && iterations > 0 {
        print!("{}", last_output);
    }

    // Print summary if requested
    if show_summary {
        println!("Total runs:\t{}", iterations);
        println!("Successes:\t{}", successes);
        println!("Failures:\t{}", failures);
    }

    // Exit with appropriate code
    if error_duration && for_duration.is_some() && start_time.elapsed() >= for_duration.unwrap() {
        std::process::exit(124);
    }
}

fn parse_duration(duration_str: &str) -> Duration {
    let mut duration = Duration::new(0, 0);
    let mut current = String::new();

    for ch in duration_str.chars() {
        if ch.is_ascii_digit() {
            current.push(ch);
        } else {
            if !current.is_empty() {
                let value: u64 = current.parse().unwrap_or(0);
                match ch {
                    'h' => duration += Duration::from_secs(value * 3600),
                    'm' => {
                        // Check if next char is 's' for ms
                        if ch == 'm' {
                            // Could be ms or m, we'll handle this carefully
                            duration += Duration::from_secs(value * 60);
                        }
                    }
                    's' => {
                        duration += Duration::from_secs(value);
                    }
                    'u' => {
                        duration += Duration::from_micros(value);
                    }
                    _ => {}
                }
                current.clear();
            }
        }
    }

    // Handle milliseconds and microseconds specially
    let duration_str_lower = duration_str.to_lowercase();
    if duration_str_lower.contains("ms") {
        // Parse milliseconds
        if let Some(pos) = duration_str_lower.find("ms") {
            let ms_part = &duration_str[..pos];
            let mut digits = String::new();
            for ch in ms_part.chars().rev() {
                if ch.is_ascii_digit() {
                    digits.insert(0, ch);
                } else {
                    break;
                }
            }
            if let Ok(ms) = digits.parse::<u64>() {
                duration = Duration::from_millis(ms);
            }
        }
    } else if duration_str_lower.contains("us") {
        // Parse microseconds
        if let Some(pos) = duration_str_lower.find("us") {
            let us_part = &duration_str[..pos];
            let mut digits = String::new();
            for ch in us_part.chars().rev() {
                if ch.is_ascii_digit() {
                    digits.insert(0, ch);
                } else {
                    break;
                }
            }
            if let Ok(us) = digits.parse::<u64>() {
                return Duration::from_micros(us);
            }
        }
    }

    duration
}
