                        }
                    }
                    's' => {
                        duration += Duration::from_secs(value);
                    }
                    'u' => {
                        duration += Duration::from_micros(value);
                    }
                    _ => {}
                }
                current.clear();
            }
        }
    }

    // Handle milliseconds and microseconds specially
    let duration_str_lower = duration_str.to_lowercase();
