                } else {
                    break;
                }
            }
            if let Ok(ms) = digits.parse::<u64>() {
                duration = Duration::from_millis(ms);
            }
        }
    } else if duration_str_lower.contains("us") {
        // Parse microseconds
        if let Some(pos) = duration_str_lower.find("us") {
            let us_part = &duration_str[..pos];
            let mut digits = String::new();
            for ch in us_part.chars().rev() {
