fn parse_duration(duration_str: &str) -> Duration {
    let duration_lower = duration_str.to_lowercase();

    // Handle special cases first
    if duration_lower.ends_with("ms") {
        if let Some(pos) = duration_lower.rfind("ms") {
            let before_ms = &duration_lower[..pos];
            let mut num_str = String::new();
            for ch in before_ms.chars().rev() {
                if ch.is_ascii_digit() {
                    num_str.insert(0, ch);
                } else {
                    break;
                }
            }
            if let Ok(ms) = num_str.parse::<u64>() {
                return Duration::from_millis(ms);
            }
        }
    }

    if duration_lower.ends_with("us") {
        if let Some(pos) = duration_lower.rfind("us") {
            let before_us = &duration_lower[..pos];
            let mut num_str = String::new();
            for ch in before_us.chars().rev() {
                if ch.is_ascii_digit() {
                    num_str.insert(0, ch);
                } else {
                    break;
                }
            }
            if let Ok(us) = num_str.parse::<u64>() {
                return Duration::from_micros(us);
            }
        }
    }

    // Parse duration like "1h30m5s"
    let mut total_millis: u64 = 0;
    let mut chars = duration_lower.chars().peekable();
    let mut current_num = String::new();

    while let Some(ch) = chars.next() {
        if ch.is_ascii_digit() {
            current_num.push(ch);
        } else {
            if !current_num.is_empty() {
                if let Ok(num) = current_num.parse::<u64>() {
                    match ch {
                        'h' => total_millis += num * 3600 * 1000,
                        'm' => {
                            // Check if followed by 's' for ms
                            if chars.peek() != Some(&'s') {
                                // It's minutes
                                total_millis += num * 60 * 1000;
                            }
                        }
                        's' => total_millis += num * 1000,
                        _ => {}
                    }
                }
                current_num.clear();
            }
        }
    }

    if total_millis == 0 {
        Duration::from_micros(1)
    } else {
        Duration::from_millis(total_millis)
    }
}

fn simple_regex_match(text: &str, pattern: &str) -> bool {
    // Very simple regex implementation for common cases
    if pattern.is_empty() {
        return true;
