        if let Some(max) = args.num {
            if iterations >= max {
                break;
            }
        }

        // Check for-duration
        if let Some(end) = duration_end {
            if Instant::now() >= end {
                break;
            }
        }

        // Determine what to iterate over
        let items_to_process: Vec<String> = if !items.is_empty() {
            items.clone()
        } else if !stdin_lines.is_empty() {
            stdin_lines.clone()
        } else {
            vec![String::new()]
        };

        for item in items_to_process {
            // Check iteration limits before executing
            if let Some(max) = args.num {
                if iterations >= max {
                    should_loop = false;
                    break;
                }
            }

            // Check for-duration before executing
            if let Some(end) = duration_end {
                if Instant::now() >= end {
                    should_loop = false;
                    break;
                }
            }

            // Build environment
            let mut cmd_env = env::vars().collect::<Vec<_>>();
            cmd_env.push(("COUNT".to_string(), counter.to_string()));
            cmd_env.push(("ACTUALCOUNT".to_string(), iterations.to_string()));
            if !item.is_empty() && (!items.is_empty() || args.stdin) {
                cmd_env.push(("ITEM".to_string(), item.clone()));
            }

            // Execute command
            let mut cmd = Command::new("sh");
            cmd.arg("-c");

            let command_str = if args.input.is_empty() {
