                }
            }

            if args.until_same && iterations > 0 {
                let current = stdout.trim();
                let prev = last_output.trim();
                if current == prev {
                    should_loop = false;
                    break;
                }
            }

            iterations += 1;
            counter += args.count_by;

            if !should_loop {
                break;
            }

            // Sleep before next iteration
            if args.every > Duration::from_secs(0) && (args.num.is_none() || iterations < args.num.unwrap()) {
                thread::sleep(args.every);
            }
        }

        if !should_loop {
