                if i + 1 < args.len() {
                    until_match = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-s" | "--until-success" => {
                until_success = true;
                i += 1;
            }
            "-f" | "--until-fail" => {
                until_fail = true;
                i += 1;
            }
            "-r" | "--until-error" => {
                if i + 1 < args.len() {
                    until_error = args[i + 1].parse().ok();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-C" | "--until-changes" => {
                until_changes = true;
                i += 1;
            }
            "-S" | "--until-same" => {
                until_same = true;
                i += 1;
            }
