fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();

    let mut num = None;
    let mut every = Duration::from_micros(1);
    let mut count_by = 1i64;
    let mut offset = 0i64;
    let mut for_list = None;
    let mut for_duration = None;
    let mut until_contains = None;
    let mut until_match = None;
    let mut until_success = false;
    let mut until_fail = false;
    let mut until_error = None;
    let mut until_changes = false;
    let mut until_same = false;
    let mut until_time = None;
    let mut stdin = false;
    let mut only_last = false;
    let mut summary = false;
    let mut error_duration = false;
    let mut input: Vec<String> = vec![];
    let mut i = 1;
    let mut skip_next_for_double_dash = false;

    while i < args.len() {
        let arg = &args[i];

        if skip_next_for_double_dash {
            input.extend(args[i..].to_vec());
            break;
        }

        match arg.as_str() {
            "--" => {
                skip_next_for_double_dash = true;
                i += 1;
            }
            "-n" | "--num" => {
                if i + 1 < args.len() {
                    num = args[i + 1].parse().ok();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-e" | "--every" => {
                if i + 1 < args.len() {
                    every = parse_duration(&args[i + 1]);
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-b" | "--count-by" => {
                if i + 1 < args.len() {
                    count_by = args[i + 1].parse().unwrap_or(1);
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-o" | "--offset" => {
                if i + 1 < args.len() {
                    offset = args[i + 1].parse().unwrap_or(0);
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--for" => {
                if i + 1 < args.len() {
                    for_list = Some(args[i + 1].split(',').map(String::from).collect());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-d" | "--for-duration" => {
                if i + 1 < args.len() {
                    for_duration = Some(parse_duration(&args[i + 1]));
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-c" | "--until-contains" => {
                if i + 1 < args.len() {
                    until_contains = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-m" | "--until-match" => {
                if i + 1 < args.len() {
                    until_match = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-s" | "--until-success" => {
                until_success = true;
                i += 1;
            }
            "-f" | "--until-fail" => {
                until_fail = true;
                i += 1;
            }
            "-r" | "--until-error" => {
                if i + 1 < args.len() {
                    until_error = args[i + 1].parse().ok();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-C" | "--until-changes" => {
                until_changes = true;
                i += 1;
            }
            "-S" | "--until-same" => {
                until_same = true;
                i += 1;
            }
            "-t" | "--until-time" => {
                if i + 1 < args.len() {
                    until_time = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-i" | "--stdin" => {
                stdin = true;
                i += 1;
            }
            "-l" | "--only-last" => {
                only_last = true;
                i += 1;
            }
            "--summary" => {
                summary = true;
                i += 1;
            }
            "-D" | "--error-duration" => {
                error_duration = true;
                i += 1;
            }
            "-h" | "--help" | "-V" | "--version" => {
                input.push(arg.clone());
                i += 1;
            }
            _ => {
                if arg.starts_with('-') {
                    i += 1;
                } else {
                    input.extend(args[i..].to_vec());
                    break;
                }
            }
        }
    }

    Args {
        num,
        every,
        count_by,
        offset,
        for_list,
        for_duration,
        until_contains,
        until_match,
        until_success,
        until_fail,
        until_error,
        until_changes,
        until_same,
        until_time,
        stdin,
        only_last,
        summary,
        error_duration,
        input,
    }
}

fn parse_duration(duration_str: &str) -> Duration {
    let duration_lower = duration_str.to_lowercase();

    // Handle special cases first
    if duration_lower.ends_with("ms") {
        if let Some(pos) = duration_lower.rfind("ms") {
            let before_ms = &duration_lower[..pos];
            let mut num_str = String::new();
            for ch in before_ms.chars().rev() {
                if ch.is_ascii_digit() {
                    num_str.insert(0, ch);
                } else {
                    break;
                }
            }
            if let Ok(ms) = num_str.parse::<u64>() {
                return Duration::from_millis(ms);
            }
        }
    }

    if duration_lower.ends_with("us") {
        if let Some(pos) = duration_lower.rfind("us") {
            let before_us = &duration_lower[..pos];
            let mut num_str = String::new();
            for ch in before_us.chars().rev() {
                if ch.is_ascii_digit() {
                    num_str.insert(0, ch);
                } else {
                    break;
                }
            }
            if let Ok(us) = num_str.parse::<u64>() {
                return Duration::from_micros(us);
            }
        }
    }

    // Parse duration like "1h30m5s"
    let mut total_millis: u64 = 0;
    let mut chars = duration_lower.chars().peekable();
    let mut current_num = String::new();

    while let Some(ch) = chars.next() {
        if ch.is_ascii_digit() {
            current_num.push(ch);
        } else {
            if !current_num.is_empty() {
                if let Ok(num) = current_num.parse::<u64>() {
                    match ch {
                        'h' => total_millis += num * 3600 * 1000,
                        'm' => {
                            // Check if followed by 's' for ms
                            if chars.peek() != Some(&'s') {
                                // It's minutes
                                total_millis += num * 60 * 1000;
                            }
                        }
                        's' => total_millis += num * 1000,
                        _ => {}
                    }
                }
                current_num.clear();
            }
        }
    }

    if total_millis == 0 {
        Duration::from_micros(1)
    } else {
        Duration::from_millis(total_millis)
    }
}

fn simple_regex_match(text: &str, pattern: &str) -> bool {
    // Very simple regex implementation for common cases
    if pattern.is_empty() {
        return true;
    }

    // If pattern doesn't have regex chars, just do contains
    if !pattern.contains(|c: char| ".*+?^$[]{}()\\|".contains(c)) {
        return text.contains(pattern);
    }

    // For now, just use a simple contains for regex patterns
    text.contains(pattern)
}

