                }
            }

            iterations += 1;
            counter += args.count_by;

            if !should_loop {
                break;
            }

            // Sleep before next iteration
            if args.every > Duration::from_secs(0) {
                if args.num.is_none() || iterations < args.num.unwrap() {
                    thread::sleep(args.every);
